// ===== 工具函数 =====
export function searchMediaByTrait(
  dim: string,
  limit: number = 8
): BFStoryMirrorMedia[] {
  return BF_STORY_MIRROR_MEDIA
    .filter(m => m.trait_connections.some(c => c.startsWith(dim)))
    .sort((a, b) => b.editorial_quality - a.editorial_quality)
    .slice(0, limit);
}

export function getMediaStats() {
  const total = BF_STORY_MIRROR_MEDIA.length;
  const byMedium: Record<string, number> = {};
  for (const m of BF_STORY_MIRROR_MEDIA) {
    byMedium[m.medium] = (byMedium[m.medium] || 0) + 1;
  }
  return { total, byMedium };
}

export default BF_STORY_MIRROR_MEDIA;
